import React, { useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import {
    Box,
    Container,
    Typography,
    Paper,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Chip,
    IconButton,
    Button,
    TextField,
    Grid,
    Card,
    CardContent,
    MenuItem,
    Select,
    FormControl,
    InputLabel,
    TablePagination,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Alert,
    Switch,
    FormControlLabel,
    Divider,
} from '@mui/material';
import {
    Visibility,
    Delete,
    Flag,
    CheckCircle,
    Warning,
    Block,
    Search,
    Logout,
} from '@mui/icons-material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';

type OrganizationType =
    | 'government_accredited_auditor'
    | 'bank_incentives_partner'
    | 'verification_agency'
    | 'other';

interface MSME {
    _id: string;
    companyName: string;
    industry: string;
    status: 'pending' | 'verified' | 'flagged' | 'suspended';
    contact: {
        email: string;
        phone: string;
    };
    gstNumber: string;
    createdAt: string;
    userId: {
        email: string;
        createdAt: string;
    };
}

interface Statistics {
    msme: {
        total: number;
        verified: number;
        flagged: number;
        pending: number;
        suspended: number;
    };
}

interface ViewRoleUser {
    _id: string;
    email: string;
    role: 'view';
    isActive: boolean;
    createdAt: string;
    lastLogin?: string;
    profile?: {
        firstName?: string;
        lastName?: string;
        phone?: string;
    };
    accessCredentials?: {
        organizationType?: OrganizationType;
        organizationName?: string;
        credentialId?: string;
        accessPurpose?: string;
        approvedAt?: string;
        approvedBy?: {
            _id?: string;
            email?: string;
            profile?: {
                firstName?: string;
                lastName?: string;
            };
        };
    };
}

interface BillingConfig {
    _id: string;
    moduleEnabled: boolean;
    methods: {
        upi: boolean;
        netBanking: boolean;
        cards: boolean;
    };
    updatedAt?: string;
}

interface BillingAnalyticsMethodItem {
    method: 'upi' | 'netBanking' | 'cards';
    count: number;
    totalAmount: number;
    sharePercent: number;
}

interface BillingAnalytics {
    totalTransactions: number;
    totalAmount: number;
    byMethod: BillingAnalyticsMethodItem[];
}

const CLOSED_DELETE_DIALOG = {
    open: false,
    msmeId: null as string | null,
    companyName: '',
};

const AdminDashboard: React.FC = () => {
    const navigate = useNavigate();
    const [msmes, setMsmes] = useState<MSME[]>([]);
    const [statistics, setStatistics] = useState<Statistics | null>(null);
    const [loading, setLoading] = useState(true);
    const [page, setPage] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(20);
    const [total, setTotal] = useState(0);
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('');
    const [viewUsers, setViewUsers] = useState<ViewRoleUser[]>([]);
    const [viewUsersLoading, setViewUsersLoading] = useState(false);
    const [creatingViewUser, setCreatingViewUser] = useState(false);
    const [updatingAccessUserId, setUpdatingAccessUserId] = useState<string | null>(null);
    const [billingConfig, setBillingConfig] = useState<BillingConfig | null>(null);
    const [billingAnalytics, setBillingAnalytics] = useState<BillingAnalytics | null>(null);
    const [billingLoading, setBillingLoading] = useState(false);
    const [billingSaving, setBillingSaving] = useState(false);
    const [billingError, setBillingError] = useState<string | null>(null);
    const [billingSuccess, setBillingSuccess] = useState<string | null>(null);
    const [viewUserError, setViewUserError] = useState<string | null>(null);
    const [viewUserSuccess, setViewUserSuccess] = useState<string | null>(null);
    const [viewUserForm, setViewUserForm] = useState({
        firstName: '',
        lastName: '',
        phone: '',
        email: '',
        password: '',
        organizationType: 'government_accredited_auditor' as OrganizationType,
        organizationName: '',
        credentialId: '',
        accessPurpose: '',
    });
    const [deleteDialog, setDeleteDialog] = useState(CLOSED_DELETE_DIALOG);
    const [error, setError] = useState<string | null>(null);
    const [isViewOnlyRole] = useState(() => {
        try {
            const adminUserRaw = localStorage.getItem('adminUser');
            const adminUser = adminUserRaw ? JSON.parse(adminUserRaw) : null;
            return adminUser?.role === 'view';
        } catch {
            return false;
        }
    });

    const getToken = () => localStorage.getItem('token');

    const fetchStatistics = useCallback(async () => {
        try {
            const response = await axios.get(
                buildApiUrl('/admin/msme/statistics'),
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );
            setStatistics(response.data.data);
        } catch (error) {
            console.error('Error fetching statistics:', error);
        }
    }, []);

    const fetchMSMEs = useCallback(async () => {
        try {
            setLoading(true);
            const response = await axios.get(
                buildApiUrl('/admin/msme/list'),
                {
                    params: {
                        page: page + 1,
                        limit: rowsPerPage,
                        search: searchTerm || undefined,
                        status: statusFilter || undefined,
                    },
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );

            setMsmes(response.data.data.msmes);
            setTotal(response.data.data.pagination.total);
        } catch (error: any) {
            console.error('Error fetching MSMEs:', error);
            if (error.response?.status === 403 || error.response?.status === 401) {
                navigate('/admin/login');
            } else {
                setError('Failed to load MSME data');
            }
        } finally {
            setLoading(false);
        }
    }, [navigate, page, rowsPerPage, searchTerm, statusFilter]);

    const fetchViewUsers = useCallback(async () => {
        try {
            setViewUsersLoading(true);
            const response = await axios.get(
                buildApiUrl('/admin/view-users'),
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );
            setViewUsers(response.data?.data?.users || []);
        } catch (fetchError: any) {
            if (fetchError.response?.status !== 403 && fetchError.response?.status !== 401) {
                setViewUserError('Failed to load credentialed view users');
            }
        } finally {
            setViewUsersLoading(false);
        }
    }, []);

    const handleViewUserInputChange = (
        event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
    ) => {
        const target = event.target as HTMLInputElement & HTMLTextAreaElement & { name?: string; value: unknown };
        const { name, value } = target;
        if (!name) return;
        setViewUserForm((prev) => ({
            ...prev,
            [name]: String(value),
        }));
    };

    const fetchBillingModule = useCallback(async () => {
        try {
            setBillingLoading(true);
            setBillingError(null);
            const response = await axios.get(
                buildApiUrl('/admin/billing-module'),
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );
            setBillingConfig(response?.data?.data?.config || null);
            setBillingAnalytics(response?.data?.data?.analytics || null);
        } catch (fetchError: any) {
            setBillingError(fetchError?.response?.data?.message || 'Failed to load billing controls');
        } finally {
            setBillingLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchStatistics();
        fetchMSMEs();
        if (!isViewOnlyRole) {
            fetchViewUsers();
            fetchBillingModule();
        }
    }, [
        fetchBillingModule,
        fetchMSMEs,
        fetchStatistics,
        fetchViewUsers,
        isViewOnlyRole,
    ]);

    const updateBillingModuleConfig = async (payload: {
        moduleEnabled?: boolean;
        methods?: Partial<BillingConfig['methods']>;
    }) => {
        try {
            setBillingSaving(true);
            setBillingError(null);
            setBillingSuccess(null);

            const response = await axios.put(
                buildApiUrl('/admin/billing-module'),
                payload,
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );

            setBillingConfig(response?.data?.data?.config || null);
            setBillingAnalytics(response?.data?.data?.analytics || null);
            setBillingSuccess(response?.data?.message || 'Billing module configuration updated');
        } catch (updateError: any) {
            setBillingError(updateError?.response?.data?.message || 'Failed to update billing module');
        } finally {
            setBillingSaving(false);
        }
    };

    const handleBillingModuleToggle = (_event: React.ChangeEvent<HTMLInputElement>, checked: boolean) => {
        updateBillingModuleConfig({ moduleEnabled: checked });
    };

    const handleBillingMethodToggle = (method: keyof BillingConfig['methods']) => (
        _event: React.ChangeEvent<HTMLInputElement>,
        checked: boolean
    ) => {
        updateBillingModuleConfig({
            methods: {
                [method]: checked,
            },
        });
    };

    const handleCreateViewUser = async (event: React.FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        setViewUserError(null);
        setViewUserSuccess(null);

        try {
            setCreatingViewUser(true);
            await axios.post(
                buildApiUrl('/admin/view-users'),
                {
                    email: viewUserForm.email.trim(),
                    password: viewUserForm.password,
                    profile: {
                        firstName: viewUserForm.firstName.trim(),
                        lastName: viewUserForm.lastName.trim(),
                        phone: viewUserForm.phone.trim(),
                    },
                    organizationType: viewUserForm.organizationType,
                    organizationName: viewUserForm.organizationName.trim(),
                    credentialId: viewUserForm.credentialId.trim(),
                    accessPurpose: viewUserForm.accessPurpose.trim(),
                },
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );

            setViewUserSuccess('Credentialed view-role user created successfully');
            setViewUserForm({
                firstName: '',
                lastName: '',
                phone: '',
                email: '',
                password: '',
                organizationType: 'government_accredited_auditor',
                organizationName: '',
                credentialId: '',
                accessPurpose: '',
            });
            fetchViewUsers();
        } catch (createError: any) {
            setViewUserError(createError?.response?.data?.message || 'Failed to create view-role user');
        } finally {
            setCreatingViewUser(false);
        }
    };

    const handleViewUserAccessChange = async (userId: string, isActive: boolean) => {
        setViewUserError(null);
        setViewUserSuccess(null);

        try {
            setUpdatingAccessUserId(userId);
            const response = await axios.patch(
                buildApiUrl(`/admin/view-users/${userId}/access`),
                { isActive },
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );

            const updatedUser = response?.data?.data?.user;
            if (updatedUser?._id) {
                setViewUsers((prevUsers) =>
                    prevUsers.map((user) => (user._id === updatedUser._id ? updatedUser : user))
                );
            } else {
                fetchViewUsers();
            }

            setViewUserSuccess(
                response?.data?.message ||
                    (isActive ? 'User access allowed successfully' : 'User access removed successfully')
            );
        } catch (updateError: any) {
            setViewUserError(updateError?.response?.data?.message || 'Failed to update user access');
        } finally {
            setUpdatingAccessUserId(null);
        }
    };

    const handleSearch = () => {
        setPage(0);
        fetchMSMEs();
    };

    const handleDelete = async () => {
        if (!deleteDialog.msmeId) return;

        try {
            await axios.delete(
                buildApiUrl(`/admin/msme/${deleteDialog.msmeId}?deleteUser=true`),
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );
            setDeleteDialog(CLOSED_DELETE_DIALOG);
            fetchMSMEs();
            fetchStatistics();
        } catch (error) {
            console.error('Error deleting MSME:', error);
            setError('Failed to delete MSME');
        }
    };

    const handleLogout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('adminUser');
        navigate('/admin/login');
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'verified':
                return 'success';
            case 'flagged':
                return 'warning';
            case 'suspended':
                return 'error';
            default:
                return 'default';
        }
    };

    const getStatusIcon = (status: string) => {
        switch (status) {
            case 'verified':
                return <CheckCircle />;
            case 'flagged':
                return <Warning />;
            case 'suspended':
                return <Block />;
            default:
                return <Flag />;
        }
    };

    const formatOrganizationType = (value?: OrganizationType) => {
        switch (value) {
            case 'government_accredited_auditor':
                return 'Government Accredited Auditor';
            case 'bank_incentives_partner':
                return 'Bank (Incentives Partner)';
            case 'verification_agency':
                return 'Verification Agency';
            case 'other':
                return 'Other';
            default:
                return 'N/A';
        }
    };

    const formatMethodLabel = (value: BillingAnalyticsMethodItem['method']) => {
        switch (value) {
            case 'netBanking':
                return 'Netbanking';
            case 'cards':
                return 'Cards';
            default:
                return 'UPI';
        }
    };

    const formatInrCurrency = (value: number) =>
        new Intl.NumberFormat('en-IN', {
            style: 'currency',
            currency: 'INR',
            maximumFractionDigits: 2,
        }).format(value || 0);

    return (
        <Box sx={{ minHeight: '100vh', bgcolor: 'grey.100', py: 4 }}>
            <Container maxWidth="xl">
                {/* Header */}
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 4 }}>
                    <Typography variant="h4" component="h1" sx={{ fontWeight: 700 }}>
                        Admin Dashboard
                    </Typography>
                    <Button
                        variant="outlined"
                        startIcon={<Logout />}
                        onClick={handleLogout}
                    >
                        Logout
                    </Button>
                </Box>

                {error && (
                    <Alert severity="error" sx={{ mb: 3 }} onClose={() => setError(null)}>
                        {error}
                    </Alert>
                )}

                {/* Statistics Cards */}
                {statistics && (
                    <Grid container spacing={3} sx={{ mb: 4 }}>
                        <Grid item xs={12} sm={6} md={2.4}>
                            <Card>
                                <CardContent>
                                    <Typography color="text.secondary" gutterBottom variant="body2">
                                        Total MSMEs
                                    </Typography>
                                    <Typography variant="h4">{statistics.msme.total}</Typography>
                                </CardContent>
                            </Card>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2.4}>
                            <Card sx={{ borderLeft: 4, borderColor: 'success.main' }}>
                                <CardContent>
                                    <Typography color="text.secondary" gutterBottom variant="body2">
                                        Verified
                                    </Typography>
                                    <Typography variant="h4" color="success.main">
                                        {statistics.msme.verified}
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2.4}>
                            <Card sx={{ borderLeft: 4, borderColor: 'warning.main' }}>
                                <CardContent>
                                    <Typography color="text.secondary" gutterBottom variant="body2">
                                        Flagged
                                    </Typography>
                                    <Typography variant="h4" color="warning.main">
                                        {statistics.msme.flagged}
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2.4}>
                            <Card sx={{ borderLeft: 4, borderColor: 'info.main' }}>
                                <CardContent>
                                    <Typography color="text.secondary" gutterBottom variant="body2">
                                        Pending
                                    </Typography>
                                    <Typography variant="h4" color="info.main">
                                        {statistics.msme.pending}
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2.4}>
                            <Card sx={{ borderLeft: 4, borderColor: 'error.main' }}>
                                <CardContent>
                                    <Typography color="text.secondary" gutterBottom variant="body2">
                                        Suspended
                                    </Typography>
                                    <Typography variant="h4" color="error.main">
                                        {statistics.msme.suspended}
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>
                    </Grid>
                )}

                {/* Filters */}
                <Paper sx={{ p: 2, mb: 3 }}>
                    <Grid container spacing={2} alignItems="center">
                        <Grid item xs={12} md={6}>
                            <TextField
                                fullWidth
                                size="small"
                                placeholder="Search by company name, email, GST, PAN..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') handleSearch();
                                }}
                                InputProps={{
                                    endAdornment: (
                                        <IconButton onClick={handleSearch} size="small" aria-label="Search MSMEs">
                                            <Search />
                                        </IconButton>
                                    ),
                                }}
                            />
                        </Grid>
                        <Grid item xs={12} md={3}>
                            <FormControl fullWidth size="small">
                                <InputLabel>Status</InputLabel>
                                <Select
                                    value={statusFilter}
                                    label="Status"
                                    onChange={(e) => {
                                        setStatusFilter(e.target.value);
                                        setPage(0);
                                    }}
                                >
                                    <MenuItem value="">All</MenuItem>
                                    <MenuItem value="pending">Pending</MenuItem>
                                    <MenuItem value="verified">Verified</MenuItem>
                                    <MenuItem value="flagged">Flagged</MenuItem>
                                    <MenuItem value="suspended">Suspended</MenuItem>
                                </Select>
                            </FormControl>
                        </Grid>
                        <Grid item xs={12} md={3}>
                            <Button
                                fullWidth
                                variant="outlined"
                                onClick={() => {
                                    setSearchTerm('');
                                    setStatusFilter('');
                                    setPage(0);
                                }}
                            >
                                Clear Filters
                            </Button>
                        </Grid>
                    </Grid>
                </Paper>

                {!isViewOnlyRole && (
                    <Paper sx={{ p: 3, mb: 3 }}>
                        <Typography variant="h6" sx={{ fontWeight: 700, mb: 1 }}>
                            Credentialed View Access Provisioning
                        </Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                            Add specific credentialed users for read-only access (e.g., government accredited auditors,
                            bank incentive partners, and verification agencies).
                        </Typography>

                        {viewUserError && (
                            <Alert severity="error" sx={{ mb: 2 }} onClose={() => setViewUserError(null)}>
                                {viewUserError}
                            </Alert>
                        )}
                        {viewUserSuccess && (
                            <Alert severity="success" sx={{ mb: 2 }} onClose={() => setViewUserSuccess(null)}>
                                {viewUserSuccess}
                            </Alert>
                        )}

                        <Box component="form" onSubmit={handleCreateViewUser} sx={{ mb: 3 }}>
                            <Grid container spacing={2}>
                                <Grid item xs={12} md={3}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        label="First Name"
                                        name="firstName"
                                        value={viewUserForm.firstName}
                                        onChange={handleViewUserInputChange}
                                        required
                                    />
                                </Grid>
                                <Grid item xs={12} md={3}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        label="Last Name"
                                        name="lastName"
                                        value={viewUserForm.lastName}
                                        onChange={handleViewUserInputChange}
                                    />
                                </Grid>
                                <Grid item xs={12} md={3}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        label="Phone"
                                        name="phone"
                                        value={viewUserForm.phone}
                                        onChange={handleViewUserInputChange}
                                    />
                                </Grid>
                                <Grid item xs={12} md={3}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        type="email"
                                        label="Email"
                                        name="email"
                                        value={viewUserForm.email}
                                        onChange={handleViewUserInputChange}
                                        required
                                    />
                                </Grid>
                                <Grid item xs={12} md={3}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        type="password"
                                        label="Temporary Password"
                                        name="password"
                                        value={viewUserForm.password}
                                        onChange={handleViewUserInputChange}
                                        required
                                        inputProps={{ minLength: 6 }}
                                    />
                                </Grid>
                                <Grid item xs={12} md={3}>
                                    <FormControl fullWidth size="small" required>
                                        <InputLabel>Organization Type</InputLabel>
                                        <Select
                                            label="Organization Type"
                                            name="organizationType"
                                            value={viewUserForm.organizationType}
                                            onChange={(event) =>
                                                setViewUserForm((prev) => ({
                                                    ...prev,
                                                    organizationType: event.target.value as OrganizationType,
                                                }))
                                            }
                                        >
                                            <MenuItem value="government_accredited_auditor">
                                                Government Accredited Auditor
                                            </MenuItem>
                                            <MenuItem value="bank_incentives_partner">
                                                Bank (Incentives Partner)
                                            </MenuItem>
                                            <MenuItem value="verification_agency">Verification Agency</MenuItem>
                                            <MenuItem value="other">Other</MenuItem>
                                        </Select>
                                    </FormControl>
                                </Grid>
                                <Grid item xs={12} md={3}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        label="Organization Name"
                                        name="organizationName"
                                        value={viewUserForm.organizationName}
                                        onChange={handleViewUserInputChange}
                                        required
                                    />
                                </Grid>
                                <Grid item xs={12} md={3}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        label="Credential ID"
                                        name="credentialId"
                                        value={viewUserForm.credentialId}
                                        onChange={handleViewUserInputChange}
                                        required
                                    />
                                </Grid>
                                <Grid item xs={12} md={9}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        label="Access Purpose"
                                        name="accessPurpose"
                                        value={viewUserForm.accessPurpose}
                                        onChange={handleViewUserInputChange}
                                        required
                                        multiline
                                        minRows={2}
                                    />
                                </Grid>
                                <Grid item xs={12} md={3} sx={{ display: 'flex', alignItems: 'center' }}>
                                    <Button
                                        type="submit"
                                        variant="contained"
                                        fullWidth
                                        disabled={creatingViewUser}
                                    >
                                        {creatingViewUser ? 'Adding User...' : 'Add View User'}
                                    </Button>
                                </Grid>
                            </Grid>
                        </Box>

                        <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 1 }}>
                            Provisioned View Users
                        </Typography>
                        <TableContainer component={Paper} variant="outlined">
                            <Table size="small">
                                <TableHead>
                                    <TableRow>
                                        <TableCell><strong>Name</strong></TableCell>
                                        <TableCell><strong>Email</strong></TableCell>
                                        <TableCell><strong>Organization</strong></TableCell>
                                        <TableCell><strong>Credential ID</strong></TableCell>
                                        <TableCell><strong>Purpose</strong></TableCell>
                                        <TableCell><strong>Approved At</strong></TableCell>
                                        <TableCell><strong>Status</strong></TableCell>
                                        <TableCell><strong>Access Control</strong></TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {viewUsersLoading ? (
                                        <TableRow>
                                            <TableCell colSpan={8} align="center">Loading view users...</TableCell>
                                        </TableRow>
                                    ) : viewUsers.length === 0 ? (
                                        <TableRow>
                                            <TableCell colSpan={8} align="center">No credentialed view users found</TableCell>
                                        </TableRow>
                                    ) : (
                                        viewUsers.map((user) => (
                                            <TableRow key={user._id} hover>
                                                <TableCell>
                                                    {[user.profile?.firstName, user.profile?.lastName]
                                                        .filter(Boolean)
                                                        .join(' ') || 'N/A'}
                                                </TableCell>
                                                <TableCell>{user.email}</TableCell>
                                                <TableCell>
                                                    <Typography variant="body2">
                                                        {user.accessCredentials?.organizationName || 'N/A'}
                                                    </Typography>
                                                    <Typography variant="caption" color="text.secondary">
                                                        {formatOrganizationType(user.accessCredentials?.organizationType)}
                                                    </Typography>
                                                </TableCell>
                                                <TableCell>{user.accessCredentials?.credentialId || 'N/A'}</TableCell>
                                                <TableCell>{user.accessCredentials?.accessPurpose || 'N/A'}</TableCell>
                                                <TableCell>
                                                    {user.accessCredentials?.approvedAt
                                                        ? new Date(user.accessCredentials.approvedAt).toLocaleDateString()
                                                        : 'N/A'}
                                                </TableCell>
                                                <TableCell>
                                                    <Chip
                                                        label={user.isActive ? 'Active' : 'Inactive'}
                                                        color={user.isActive ? 'success' : 'default'}
                                                        size="small"
                                                    />
                                                </TableCell>
                                                <TableCell>
                                                    <Button
                                                        size="small"
                                                        variant={user.isActive ? 'outlined' : 'contained'}
                                                        color={user.isActive ? 'error' : 'success'}
                                                        disabled={updatingAccessUserId === user._id}
                                                        onClick={() =>
                                                            handleViewUserAccessChange(user._id, !user.isActive)
                                                        }
                                                    >
                                                        {updatingAccessUserId === user._id
                                                            ? 'Updating...'
                                                            : user.isActive
                                                                ? 'Remove Access'
                                                                : 'Allow User'}
                                                    </Button>
                                                </TableCell>
                                            </TableRow>
                                        ))
                                    )}
                                </TableBody>
                            </Table>
                        </TableContainer>
                    </Paper>
                )}

                {!isViewOnlyRole && (
                    <Paper sx={{ p: 3, mb: 3 }}>
                        <Typography variant="h6" sx={{ fontWeight: 700, mb: 1 }}>
                            Billing Module Control
                        </Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                            Configure billing module availability, control payment methods, and monitor billing analytics.
                        </Typography>

                        {billingError && (
                            <Alert severity="error" sx={{ mb: 2 }} onClose={() => setBillingError(null)}>
                                {billingError}
                            </Alert>
                        )}
                        {billingSuccess && (
                            <Alert severity="success" sx={{ mb: 2 }} onClose={() => setBillingSuccess(null)}>
                                {billingSuccess}
                            </Alert>
                        )}

                        {billingLoading ? (
                            <Typography variant="body2" color="text.secondary">
                                Loading billing controls...
                            </Typography>
                        ) : billingConfig ? (
                            <>
                                <Grid container spacing={2} sx={{ mb: 2 }}>
                                    <Grid item xs={12} md={4}>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 1 }}>
                                                Module Status
                                            </Typography>
                                            <FormControlLabel
                                                control={(
                                                    <Switch
                                                        checked={billingConfig.moduleEnabled}
                                                        onChange={handleBillingModuleToggle}
                                                        disabled={billingSaving}
                                                    />
                                                )}
                                                label={billingConfig.moduleEnabled ? 'Enabled' : 'Disabled'}
                                            />
                                            <Chip
                                                label={billingConfig.moduleEnabled ? 'Live for configured methods' : 'Module disabled'}
                                                color={billingConfig.moduleEnabled ? 'success' : 'default'}
                                                size="small"
                                                sx={{ mt: 1 }}
                                            />
                                        </Paper>
                                    </Grid>
                                    <Grid item xs={12} md={8}>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 1 }}>
                                                Payment Methods
                                            </Typography>
                                            <Grid container spacing={1}>
                                                <Grid item xs={12} sm={4}>
                                                    <FormControlLabel
                                                        control={(
                                                            <Switch
                                                                checked={billingConfig.methods?.upi || false}
                                                                onChange={handleBillingMethodToggle('upi')}
                                                                disabled={billingSaving}
                                                            />
                                                        )}
                                                        label="UPI Payment"
                                                    />
                                                </Grid>
                                                <Grid item xs={12} sm={4}>
                                                    <FormControlLabel
                                                        control={(
                                                            <Switch
                                                                checked={billingConfig.methods?.netBanking || false}
                                                                onChange={handleBillingMethodToggle('netBanking')}
                                                                disabled={billingSaving}
                                                            />
                                                        )}
                                                        label="Netbanking"
                                                    />
                                                </Grid>
                                                <Grid item xs={12} sm={4}>
                                                    <FormControlLabel
                                                        control={(
                                                            <Switch
                                                                checked={billingConfig.methods?.cards || false}
                                                                onChange={handleBillingMethodToggle('cards')}
                                                                disabled={billingSaving}
                                                            />
                                                        )}
                                                        label="Cards Payment"
                                                    />
                                                </Grid>
                                            </Grid>
                                        </Paper>
                                    </Grid>
                                </Grid>

                                <Divider sx={{ my: 2 }} />

                                <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 1 }}>
                                    Billing Analytics
                                </Typography>
                                <Grid container spacing={2} sx={{ mb: 2 }}>
                                    <Grid item xs={12} md={4}>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Typography variant="body2" color="text.secondary">
                                                Total Billing Transactions
                                            </Typography>
                                            <Typography variant="h6">
                                                {billingAnalytics?.totalTransactions ?? 0}
                                            </Typography>
                                        </Paper>
                                    </Grid>
                                    <Grid item xs={12} md={4}>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Typography variant="body2" color="text.secondary">
                                                Total Billing Amount
                                            </Typography>
                                            <Typography variant="h6">
                                                {formatInrCurrency(billingAnalytics?.totalAmount ?? 0)}
                                            </Typography>
                                        </Paper>
                                    </Grid>
                                    <Grid item xs={12} md={4}>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Typography variant="body2" color="text.secondary">
                                                Last Config Update
                                            </Typography>
                                            <Typography variant="h6">
                                                {billingConfig.updatedAt
                                                    ? new Date(billingConfig.updatedAt).toLocaleDateString()
                                                    : 'N/A'}
                                            </Typography>
                                        </Paper>
                                    </Grid>
                                </Grid>

                                <TableContainer component={Paper} variant="outlined">
                                    <Table size="small">
                                        <TableHead>
                                            <TableRow>
                                                <TableCell><strong>Method</strong></TableCell>
                                                <TableCell><strong>Transactions</strong></TableCell>
                                                <TableCell><strong>Total Amount</strong></TableCell>
                                                <TableCell><strong>Share</strong></TableCell>
                                            </TableRow>
                                        </TableHead>
                                        <TableBody>
                                            {(billingAnalytics?.byMethod || []).map((methodItem) => (
                                                <TableRow key={methodItem.method}>
                                                    <TableCell>{formatMethodLabel(methodItem.method)}</TableCell>
                                                    <TableCell>{methodItem.count}</TableCell>
                                                    <TableCell>{formatInrCurrency(methodItem.totalAmount)}</TableCell>
                                                    <TableCell>{methodItem.sharePercent.toFixed(2)}%</TableCell>
                                                </TableRow>
                                            ))}
                                        </TableBody>
                                    </Table>
                                </TableContainer>
                            </>
                        ) : (
                            <Typography variant="body2" color="text.secondary">
                                Billing module configuration is currently unavailable.
                            </Typography>
                        )}
                    </Paper>
                )}

                {/* MSME Table */}
                <TableContainer component={Paper} sx={{ border: 1, borderColor: 'divider', borderRadius: 2 }}>
                    <Table aria-label="MSME registry table" stickyHeader>
                        <TableHead>
                            <TableRow>
                                <TableCell><strong>Company Name</strong></TableCell>
                                <TableCell><strong>Industry</strong></TableCell>
                                <TableCell><strong>Email</strong></TableCell>
                                <TableCell><strong>Status</strong></TableCell>
                                <TableCell><strong>Registered</strong></TableCell>
                                <TableCell align="center"><strong>{isViewOnlyRole ? 'View' : 'Actions'}</strong></TableCell>
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            {loading ? (
                                <TableRow>
                                    <TableCell colSpan={6} align="center" sx={{ py: 4 }}>
                                        <Typography variant="body2" color="text.secondary">
                                            Loading MSME registry records...
                                        </Typography>
                                    </TableCell>
                                </TableRow>
                            ) : msmes.length === 0 ? (
                                <TableRow>
                                    <TableCell colSpan={6} align="center" sx={{ py: 4 }}>
                                        <Typography variant="body2" color="text.secondary">
                                            No MSMEs matched the current filters.
                                        </Typography>
                                        <Button
                                            sx={{ mt: 1.5 }}
                                            size="small"
                                            onClick={() => {
                                                setSearchTerm('');
                                                setStatusFilter('');
                                                setPage(0);
                                            }}
                                        >
                                            Reset filters
                                        </Button>
                                    </TableCell>
                                </TableRow>
                            ) : (
                                msmes.map((msme) => (
                                    <TableRow
                                        key={msme._id}
                                        hover
                                        sx={{
                                            '&:nth-of-type(odd)': { bgcolor: 'action.hover' },
                                            '&:hover': { bgcolor: 'action.selected' },
                                        }}
                                    >
                                        <TableCell>{msme.companyName}</TableCell>
                                        <TableCell>{msme.industry}</TableCell>
                                        <TableCell>{msme.contact.email}</TableCell>
                                        <TableCell>
                                            <Chip
                                                icon={getStatusIcon(msme.status || 'pending')}
                                                label={msme.status ? msme.status.charAt(0).toUpperCase() + msme.status.slice(1) : 'Pending'}
                                                color={getStatusColor(msme.status || 'pending') as any}
                                                size="small"
                                            />
                                        </TableCell>
                                        <TableCell>
                                            {new Date(msme.createdAt).toLocaleDateString()}
                                        </TableCell>
                                        <TableCell align="center">
                                            <IconButton
                                                size="small"
                                                onClick={() => navigate(`/admin/msme/${msme._id}`)}
                                                title="View Details"
                                                aria-label={`View ${msme.companyName} details`}
                                            >
                                                <Visibility />
                                            </IconButton>
                                            {!isViewOnlyRole && (
                                                <IconButton
                                                    size="small"
                                                    color="error"
                                                    onClick={() =>
                                                        setDeleteDialog({
                                                            open: true,
                                                            msmeId: msme._id,
                                                            companyName: msme.companyName,
                                                        })
                                                    }
                                                    title="Delete MSME"
                                                    aria-label={`Delete ${msme.companyName}`}
                                                >
                                                    <Delete />
                                                </IconButton>
                                            )}
                                        </TableCell>
                                    </TableRow>
                                ))
                            )}
                        </TableBody>
                    </Table>
                    <TablePagination
                        rowsPerPageOptions={[10, 20, 50]}
                        component="div"
                        count={total}
                        rowsPerPage={rowsPerPage}
                        page={page}
                        onPageChange={(_, newPage) => setPage(newPage)}
                        onRowsPerPageChange={(e) => {
                            setRowsPerPage(parseInt(e.target.value, 10));
                            setPage(0);
                        }}
                    />
                </TableContainer>

                {/* Delete Confirmation Dialog */}
                {!isViewOnlyRole && (
                    <Dialog open={deleteDialog.open} onClose={() => setDeleteDialog(CLOSED_DELETE_DIALOG)}>
                        <DialogTitle>Confirm Deletion</DialogTitle>
                        <DialogContent>
                            <Alert severity="warning" sx={{ mt: 1 }}>
                                This action is permanent and will remove the MSME profile and linked user account.
                            </Alert>
                            <Typography sx={{ mt: 2 }}>
                                Company selected: <strong>{deleteDialog.companyName || 'N/A'}</strong>
                            </Typography>
                        </DialogContent>
                        <DialogActions>
                            <Button onClick={() => setDeleteDialog(CLOSED_DELETE_DIALOG)}>
                                Cancel
                            </Button>
                            <Button onClick={handleDelete} color="error" variant="contained">
                                Delete
                            </Button>
                        </DialogActions>
                    </Dialog>
                )}
            </Container>
        </Box>
    );
};

export default AdminDashboard;
