import React, { useMemo } from 'react';
import { Alert, Stack, Typography } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import { useLocation } from 'react-router-dom';
import { PAGE_BANNER_HIDDEN_ROUTES, resolvePageInfo } from '../utils/routePageMeta';

interface PageInformationBannerProps {
  compact?: boolean;
}

const PageInformationBanner: React.FC<PageInformationBannerProps> = ({ compact = false }) => {
  const location = useLocation();
  const theme = useTheme();

  const info = useMemo(() => resolvePageInfo(location.pathname || '/'), [location.pathname]);

  if (PAGE_BANNER_HIDDEN_ROUTES.has(location.pathname || '')) {
    return null;
  }

  return (
    <Alert
      severity="info"
      variant="outlined"
      sx={{
        mb: compact ? 0 : 1,
        borderColor: 'info.light',
        background:
          theme.palette.mode === 'light'
            ? 'linear-gradient(130deg, rgba(33, 150, 243, 0.08), rgba(76, 175, 80, 0.05))'
            : 'linear-gradient(130deg, rgba(33, 150, 243, 0.18), rgba(76, 175, 80, 0.12))',
        py: compact ? 0.25 : undefined,
      }}
    >
      <Stack direction={{ xs: 'column', md: 'row' }} spacing={1.5} alignItems={{ xs: 'flex-start', md: 'center' }}>
        <Stack spacing={0.5} sx={{ flex: 1 }}>
          <Typography
            variant={compact ? 'body2' : 'subtitle1'}
            sx={{ fontWeight: 700, letterSpacing: 0.1 }}
          >
            {info.title}
          </Typography>
          <Typography
            variant="body2"
            color="text.secondary"
            sx={{ lineHeight: 1.45, maxWidth: { md: '72ch' } }}
          >
            {info.pageDescription}
          </Typography>
        </Stack>
      </Stack>
    </Alert>
  );
};

export default PageInformationBanner;
