import React, { useMemo, useState } from 'react';
import {
  AppBar,
  Avatar,
  Box,
  Button,
  Chip,
  Divider,
  Drawer,
  FormControlLabel,
  IconButton,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  ListSubheader,
  Menu,
  MenuItem,
  Stack,
  Switch,
  Toolbar,
  Typography,
  useMediaQuery,
} from '@mui/material';
import { useTheme } from '@mui/material/styles';
import {
  AccountCircle as AccountIcon,
  Assessment as CarbonAssessmentNavIcon,
  ChevronRight as NavTabSeparatorIcon,
  Description as DocumentsNavIcon,
  ExpandMore as ExpandMoreIcon,
  HelpOutline as HelpIcon,
  Home as HomeNavIcon,
  InfoOutlined as InfoIcon,
  Login as LoginIcon,
  Logout as LogoutIcon,
  Menu as MenuIcon,
  DarkMode as DarkModeIcon,
  LightMode as LightModeIcon,
  PersonAdd as RegisterIcon,
  Security as PrivacyIcon,
  Settings as SettingsIcon,
  Badge as ProfileNavIcon,
  Summarize as ReportsNavIcon,
  TrendingDown as EmissionsTargetsNavIcon,
} from '@mui/icons-material';
import { useNavigate, useLocation } from 'react-router-dom';
import { useRegistration } from '../context/RegistrationContext';
import { useThemeMode } from '../context/ThemeModeContext';
import { BASELINE_SOFTWARE_VERSION } from '../constants/version';
import PageInformationBanner from './PageInformationBanner';
import { BRAND_DASHBOARD_MARK_SRC } from '../constants/brand';

interface NavigationItem {
  path: string;
  label: string;
  icon: React.ReactElement;
}

const getNavItemStyles = (active: boolean, mode: 'light' | 'dark') => ({
  display: 'flex',
  alignItems: 'center',
  px: 2,
  py: 1,
  borderRadius: 2,
  cursor: 'pointer',
  transition: 'background-color 0.2s ease, color 0.2s ease, box-shadow 0.2s ease',
  backgroundColor: active
    ? mode === 'light'
      ? 'rgba(76, 175, 80, 0.12)'
      : 'rgba(76, 175, 80, 0.2)'
    : 'transparent',
  boxShadow: active && mode === 'light' ? 'inset 0 0 0 1px rgba(76, 175, 80, 0.22)' : 'none',
  '&:hover': {
    backgroundColor: active
      ? mode === 'light'
        ? 'rgba(76, 175, 80, 0.16)'
        : 'rgba(76, 175, 80, 0.26)'
      : mode === 'light'
        ? 'rgba(15, 23, 42, 0.05)'
        : 'rgba(255, 255, 255, 0.06)',
  },
  '&:focus-visible': {
    outline: '2px solid',
    outlineColor: 'primary.main',
    outlineOffset: 2,
  },
});

const Header: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const [moreAnchorEl, setMoreAnchorEl] = useState<null | HTMLElement>(null);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const { isRegistered, hasCompletedRegistration, logout } = useRegistration();
  const { isDarkMode, toggleThemeMode } = useThemeMode();
  const publicRoutes = useMemo(
    () => new Set(['/','/login','/register','/forgot-password','/help','/privacy-policy','/terms-of-service']),
    []
  );

  const handleMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleMoreMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
    setMoreAnchorEl(event.currentTarget);
  };

  const handleMoreMenuClose = () => {
    setMoreAnchorEl(null);
  };

  const handleDrawerClose = () => {
    setIsDrawerOpen(false);
  };

  const handleNavigation = (path: string) => {
    if (!isRegistered && !publicRoutes.has(path)) {
      navigate('/');
      handleMenuClose();
      handleMoreMenuClose();
      handleDrawerClose();
      return;
    }

    navigate(path);
    handleMenuClose();
    handleMoreMenuClose();
    handleDrawerClose();
  };

  const isActive = (path: string) => {
    return location.pathname === path || location.pathname.startsWith(`${path}/`);
  };

  const handleAuthAction = () => {
    handleMenuClose();
    handleMoreMenuClose();
    handleDrawerClose();

    if (isRegistered) {
      logout();
      navigate('/');
      return;
    }

    navigate('/');
  };

  const focusNavItem = (path: string) => {
    const selector = `[data-nav-path="${path}"]`;
    const navElement = document.querySelector<HTMLElement>(selector);
    navElement?.focus();
  };

  const desktopPrimaryItems: NavigationItem[] = useMemo(
    () => [
      { path: '/dashboard', label: 'Home', icon: <HomeNavIcon /> },
      { path: '/msme-profile', label: 'Profile', icon: <ProfileNavIcon /> },
      { path: '/data', label: 'Documents', icon: <DocumentsNavIcon /> },
      {
        path: '/carbon-footprint',
        label: 'Carbon Assessment',
        icon: <CarbonAssessmentNavIcon />,
      },
      {
        path: '/emissions-reduction-targets',
        label: 'Emissions targets',
        icon: <EmissionsTargetsNavIcon />,
      },
      { path: '/reporting', label: 'Reports', icon: <ReportsNavIcon /> },
    ],
    []
  );

  const desktopSecondaryItems: NavigationItem[] = useMemo(
    () => [
      { path: '/information', label: 'Information', icon: <InfoIcon /> },
      { path: '/data-privacy', label: 'Data Privacy', icon: <PrivacyIcon /> },
      { path: '/help', label: 'Help Center', icon: <HelpIcon /> },
    ],
    []
  );

  const mobileSections = useMemo(() => {
    if (!isRegistered) {
      return [
        {
          title: 'Account',
          items: [
            { path: '/login', label: 'Login', icon: <LoginIcon /> },
            { path: '/register', label: 'Create Account', icon: <RegisterIcon /> },
            { path: '/forgot-password', label: 'Forgot Password', icon: <SettingsIcon /> },
          ],
        },
        {
          title: 'Support',
          items: [
            { path: '/help', label: 'Help Center', icon: <HelpIcon /> },
            { path: '/privacy-policy', label: 'Privacy Policy', icon: <PrivacyIcon /> },
          ],
        },
      ];
    }

    return [
      { title: 'Core', items: desktopPrimaryItems },
      {
        title: 'Advanced',
        items: desktopSecondaryItems.filter((item) => item.path !== '/help'),
      },
      {
        title: 'Support',
        items: [
          { path: '/settings', label: 'Settings', icon: <SettingsIcon /> },
          { path: '/help', label: 'Help Center', icon: <HelpIcon /> },
        ],
      },
    ];
  }, [isRegistered, desktopPrimaryItems, desktopSecondaryItems]);

  const isMoreMenuActive = desktopSecondaryItems.some((item) => isActive(item.path));

  const mode = theme.palette.mode;

  const handlePrimaryNavKeyDown = (event: React.KeyboardEvent<HTMLElement>, itemIndex: number) => {
    const itemCount = desktopPrimaryItems.length;

    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      handleNavigation(desktopPrimaryItems[itemIndex].path);
      return;
    }

    if (itemCount === 0) {
      return;
    }

    if (event.key === 'ArrowRight') {
      event.preventDefault();
      const nextIndex = (itemIndex + 1) % itemCount;
      focusNavItem(desktopPrimaryItems[nextIndex].path);
      return;
    }

    if (event.key === 'ArrowLeft') {
      event.preventDefault();
      const previousIndex = (itemIndex - 1 + itemCount) % itemCount;
      focusNavItem(desktopPrimaryItems[previousIndex].path);
      return;
    }

    if (event.key === 'Home') {
      event.preventDefault();
      focusNavItem(desktopPrimaryItems[0].path);
      return;
    }

    if (event.key === 'End') {
      event.preventDefault();
      focusNavItem(desktopPrimaryItems[itemCount - 1].path);
    }
  };

  return (
    <AppBar
      position="sticky"
      elevation={0}
      color="inherit"
      sx={{
        bgcolor: 'background.paper',
        borderBottom: '1px solid',
        borderColor: 'divider',
        backdropFilter: 'blur(14px)',
        backgroundImage:
          mode === 'light'
            ? 'linear-gradient(180deg, rgba(255,255,255,0.92) 0%, rgba(255,255,255,0.78) 100%)'
            : 'linear-gradient(180deg, rgba(26,34,44,0.96) 0%, rgba(26,34,44,0.88) 100%)',
      }}
    >
      <Toolbar sx={{ py: 1, minHeight: { xs: 68, md: 76 } }}>
        {/* Logo and Brand */}
        <Box 
          sx={{ 
            display: 'flex', 
            alignItems: 'center', 
            cursor: 'pointer',
            mr: 4
          }}
          onClick={() => handleNavigation(isRegistered ? '/dashboard' : '/')}
        >
          <Box
            component="img"
            src={BRAND_DASHBOARD_MARK_SRC}
            alt="sustainow Carbon Intelligence"
            sx={{ width: 80, height: 40, mr: 1, flexShrink: 0, objectFit: 'contain' }}
          />
          <Box>
            <Typography variant="h5" component="div" sx={{ 
              fontWeight: 700,
              color: 'text.primary',
              lineHeight: 1.2,
              letterSpacing: '-0.02em',
            }}>
              Carbon Intelligence
            </Typography>
            <Stack direction="row" spacing={1} alignItems="center">
              <Typography variant="caption" sx={{ 
                display: { xs: 'none', sm: 'block' },
                color: 'text.secondary',
                fontWeight: 500
              }}>
                MSME Carbon Workspace
              </Typography>
              <Chip
                size="small"
                label={`Version ${BASELINE_SOFTWARE_VERSION}`}
                sx={{
                  height: 20,
                  '& .MuiChip-label': {
                    px: 1,
                    fontSize: '0.68rem',
                    fontWeight: 700,
                    letterSpacing: 0.2,
                  },
                  display: { xs: 'none', sm: 'inline-flex' },
                }}
                variant="outlined"
                color="default"
              />
            </Stack>
          </Box>
        </Box>

        {/* Navigation Items */}
        <Box
          sx={{ 
            display: { xs: 'none', md: 'flex' }, 
            alignItems: 'center',
            gap: 1,
            flexGrow: 1
          }}
        >
          {isRegistered ? (
            desktopPrimaryItems.map((item, itemIndex) => (
              <React.Fragment key={item.path}>
                <Box
                  onClick={() => handleNavigation(item.path)}
                  role="button"
                  tabIndex={0}
                  data-nav-path={item.path}
                  aria-label={`Navigate to ${item.label}`}
                  aria-current={isActive(item.path) ? 'page' : undefined}
                  onKeyDown={(event) => handlePrimaryNavKeyDown(event, itemIndex)}
                  sx={getNavItemStyles(isActive(item.path), mode)}
                >
                  <Box sx={{ mr: 1, display: 'flex', alignItems: 'center', color: isActive(item.path) ? 'primary.main' : 'text.secondary' }}>
                    {item.icon}
                  </Box>
                  <Typography 
                    variant="body2" 
                    sx={{ 
                      fontWeight: isActive(item.path) ? 600 : 500,
                      color: isActive(item.path) ? 'text.primary' : 'text.secondary',
                      fontSize: '0.875rem'
                    }}
                  >
                    {item.label}
                  </Typography>
                </Box>
                {itemIndex < desktopPrimaryItems.length - 1 && (
                  <NavTabSeparatorIcon
                    sx={{
                      fontSize: '1.1rem',
                      color: 'text.disabled',
                      flexShrink: 0,
                      pointerEvents: 'none',
                    }}
                    aria-hidden
                  />
                )}
              </React.Fragment>
            ))
          ) : (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <Typography
                variant="body2"
                sx={{
                  color: 'text.secondary',
                  fontWeight: 500,
                  mr: 1,
                }}
              >
                Get started
              </Typography>
              <Button color="primary" size="small" variant="text" onClick={() => handleNavigation('/login')}>
                Login
              </Button>
              <Button color="primary" size="small" variant="outlined" onClick={() => handleNavigation('/register')}>
                Register
              </Button>
              <Button color="inherit" size="small" onClick={() => handleNavigation('/help')}>
                Help
              </Button>
            </Box>
          )}

          {isRegistered && (
            <>
              <Button
                color="inherit"
                onClick={handleMoreMenuOpen}
                endIcon={<ExpandMoreIcon />}
                sx={{
                  borderRadius: 2,
                  px: 1.5,
                  py: 1,
                  color: 'text.primary',
                  backgroundColor: isMoreMenuActive
                    ? mode === 'light'
                      ? 'rgba(76, 175, 80, 0.1)'
                      : 'rgba(76, 175, 80, 0.18)'
                    : 'transparent',
                  '&:hover': {
                    backgroundColor: isMoreMenuActive
                      ? mode === 'light'
                        ? 'rgba(76, 175, 80, 0.14)'
                        : 'rgba(76, 175, 80, 0.24)'
                      : mode === 'light'
                        ? 'rgba(15, 23, 42, 0.05)'
                        : 'rgba(255, 255, 255, 0.06)',
                  },
                }}
              >
                More
              </Button>
              <Menu
                anchorEl={moreAnchorEl}
                open={Boolean(moreAnchorEl)}
                onClose={handleMoreMenuClose}
                PaperProps={{ sx: { mt: 1, minWidth: 230, borderRadius: 2 } }}
                transformOrigin={{ horizontal: 'right', vertical: 'top' }}
                anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
              >
                {desktopSecondaryItems.map((item) => (
                  <MenuItem key={item.path} onClick={() => handleNavigation(item.path)}>
                    <ListItemIcon>{item.icon}</ListItemIcon>
                    <ListItemText>{item.label}</ListItemText>
                  </MenuItem>
                ))}
              </Menu>
            </>
          )}
        </Box>

        <Box sx={{ display: { xs: 'flex', md: 'none' }, mr: 1 }}>
          <IconButton
            size="large"
            aria-label="open navigation menu"
            onClick={() => setIsDrawerOpen(true)}
            sx={{ color: 'text.primary' }}
          >
            <MenuIcon />
          </IconButton>
        </Box>

        {/* User Menu */}
        <Box sx={{ display: 'flex', alignItems: 'center' }}>
          <FormControlLabel
            sx={{
              mr: 1,
              ml: 0,
              color: 'text.secondary',
              display: { xs: 'none', sm: 'flex' },
            }}
            control={(
              <Switch
                checked={isDarkMode}
                onChange={toggleThemeMode}
                inputProps={{ 'aria-label': 'toggle dark mode' }}
                color="primary"
              />
            )}
            label={isDarkMode ? <DarkModeIcon fontSize="small" /> : <LightModeIcon fontSize="small" />}
            labelPlacement="start"
          />
          <IconButton
            size="large"
            aria-label="open user menu"
            onClick={handleMenuOpen}
            sx={{ 
              color: 'text.primary',
              '&:hover': {
                backgroundColor: mode === 'light' ? 'rgba(15, 23, 42, 0.06)' : 'rgba(255, 255, 255, 0.08)',
              }
            }}
          >
            <Avatar sx={{ width: 32, height: 32, bgcolor: 'primary.main', color: 'primary.contrastText' }}>
              <AccountIcon />
            </Avatar>
          </IconButton>
          
          <Menu
            anchorEl={anchorEl}
            open={Boolean(anchorEl)}
            onClose={handleMenuClose}
            PaperProps={{
              sx: {
                mt: 1,
                borderRadius: 2,
                minWidth: 200,
                boxShadow: '0 8px 32px rgba(0, 0, 0, 0.12)',
              },
            }}
            transformOrigin={{ horizontal: 'right', vertical: 'top' }}
            anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
          >
            {isRegistered && (
              <MenuItem onClick={() => handleNavigation('/settings')}>
                <ListItemIcon>
                  <SettingsIcon fontSize="small" />
                </ListItemIcon>
                <ListItemText>Settings</ListItemText>
              </MenuItem>
            )}

            <MenuItem onClick={toggleThemeMode}>
              <ListItemIcon>
                {isDarkMode ? <DarkModeIcon fontSize="small" /> : <LightModeIcon fontSize="small" />}
              </ListItemIcon>
              <ListItemText>{isDarkMode ? 'Dark Mode' : 'Light Mode'}</ListItemText>
            </MenuItem>
            
            <Divider />

            {!isRegistered && (
              <>
              <MenuItem onClick={() => handleNavigation('/forgot-password')}>
                <ListItemIcon>
                  <SettingsIcon fontSize="small" />
                </ListItemIcon>
                <ListItemText>Forgot Password</ListItemText>
              </MenuItem>
              <MenuItem onClick={() => handleNavigation('/register')}>
                <ListItemIcon>
                  <RegisterIcon fontSize="small" />
                </ListItemIcon>
                <ListItemText>Create Account</ListItemText>
              </MenuItem>
              <Divider />
              </>
            )}
            
            <MenuItem onClick={handleAuthAction}>
              <ListItemIcon>
                <LogoutIcon fontSize="small" />
              </ListItemIcon>
              <ListItemText>
                {isRegistered ? 'Logout' : hasCompletedRegistration ? 'Login' : 'Back to Registration'}
              </ListItemText>
            </MenuItem>
          </Menu>
        </Box>
      </Toolbar>
      <Box sx={{ px: { xs: 1.5, md: 3 }, pb: 1.25 }}>
        <PageInformationBanner />
      </Box>

      <Drawer
        anchor="right"
        open={isDrawerOpen}
        onClose={handleDrawerClose}
        PaperProps={{
          sx: {
            width: isMobile ? '88vw' : 360,
            maxWidth: 400,
            borderTopLeftRadius: 12,
            borderBottomLeftRadius: 12,
          },
        }}
      >
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
          <Box sx={{ p: 2 }}>
            <Typography variant="h6" sx={{ fontWeight: 700 }}>
              Navigation
            </Typography>
            <Typography variant="body2" color="text.secondary">
              {isRegistered ? 'Use grouped links to find features faster' : 'Sign in, register, or get support'}
            </Typography>
          </Box>
          <Divider />
          <Box sx={{ px: 2, pt: 2 }}>
            <FormControlLabel
              sx={{ m: 0 }}
              control={(
                <Switch
                  checked={isDarkMode}
                  onChange={toggleThemeMode}
                  inputProps={{ 'aria-label': 'toggle dark mode mobile' }}
                />
              )}
              label={isDarkMode ? 'Dark Background' : 'Light Background'}
            />
          </Box>
          <List sx={{ pt: 0.5 }}>
            {mobileSections.map((section) => (
              <React.Fragment key={section.title}>
                <ListSubheader sx={{ lineHeight: 2.2 }}>{section.title}</ListSubheader>
                {section.items.map((item) => (
                  <ListItemButton
                    key={item.path}
                    selected={isActive(item.path)}
                    onClick={() => handleNavigation(item.path)}
                  >
                    <ListItemIcon>{item.icon}</ListItemIcon>
                    <ListItemText primary={item.label} />
                  </ListItemButton>
                ))}
              </React.Fragment>
            ))}
          </List>
          <Box sx={{ mt: 'auto', p: 2 }}>
            <Button fullWidth variant="contained" onClick={handleAuthAction}>
              {isRegistered ? 'Logout' : 'Go to Login'}
            </Button>
          </Box>
        </Box>
      </Drawer>
    </AppBar>
  );
};

export default Header;